"""
apply_day12.py  -  ONE FILE that upgrades your production-rag project to Day 12.

HOW TO USE (Windows CMD), from inside your production-rag folder:
    .venv\\Scripts\\activate
    python apply_day12.py

What it does:
  1. Backs up every file it is about to change into  _backup_before_day12\\
  2. Writes all Day 1-12 code, tests, scripts, evals, docs and the CI workflow
  3. NEVER touches: .env, .venv, app\\storage, evals\\reports
  4. Runs  pip install -r requirements.txt   (adds hnswlib -- a C++ extension;
     if it fails to build, the rest of the app still works fine using the
     default brute_force vector index backend, which needs no extra package)
  5. Runs  python scripts\\verify_day12.py  (tests + a benchmark + a real /ask call)

Options:
    --no-install    skip pip install
    --no-verify     skip the verification run
    --offline       verification without a live call (benchmark still runs, it's free)
    --force         run even if this does not look like a production-rag folder
"""

